[19237]={h=150765883,n="Sayges spådom nr 19",d="De bortglömda har något i görningen."},
[19238]={h=4176131166,n="Sayges spådom nr 3",d="En fiende från ditt förflutna blir snart en bundsförvant."},
[19239]={h=3226725209,n="Sayges spådom nr 4",d="Lyckan följer dig i allt du företar dig."},
[19240]={h=3287993565,n="Sayges spådom nr 5",d="Någon talar väl om dig."},
[19241]={h=3447034857,n="Sayges spådom nr 6",d="Var försiktig när du landar i obekant mark."},
[19242]={h=1194860847,n="Sayges spådom nr 7",d="Undvik onödiga vågspel."},
[19243]={h=1045382223,n="Sayges spådom nr 8",d="Du kommer att göra en förmögenhet."},
[19244]={h=317721766,n="Sayges spådom nr 9",d="Din första och sista kärlek är kärleken till dig själv."},
[19245]={h=1286561138,n="Sayges spådom nr 10",d="Vila är gott, men leda är dess broder."},
[19246]={h=2370263136,n="Sayges spådom nr 11",d="Den som har enkel smak blir alltid nöjd med det bästa."},
[19247]={h=1923311044,n="Sayges spådom nr 12",d="Låt inte krigets vågor skölja bort dig."},
[19248]={h=544501652,n="Sayges spådom nr 13",d="Du lämnar dina motståndare mållösa."},
[19249]={h=1520628842,n="Sayges spådom nr 14",d="Du har gott öga för hyckleri."},
[19250]={h=661686279,n="Sayges spådom nr 15",d="Man lär sig mest när man undervisar andra."},
[19251]={h=903197727,n="Sayges spådom nr 16",d="Snart är det dags för dig att välja i en brådskande sak."},
[19252]={h=843953382,n="Sayges spådom nr 18",d="Anta nästa förslag du hör."},
[19253]={h=2687880724,n="Sayges spådom nr 17",d="Sparka aldrig iväg en gnom utan goda skäl."},
[19254]={h=2008924212,n="Sayges spådom nr 21",d="Gudomlig sköld och hemsten gör ingen hjälte hjältemodig."},
[19255]={h=297553246,n="Sayges spådom nr 22",d="Ett svar i blått är alltid sant."},
[19256]={h=276317846,n="Sayges spådom nr 2",d="Du hittar något underbart i morgon."},
