[286259]={n="Svagt glödande ben"},
[286263]={h=3525777095,n="Muradin Bronzebeards silvermynt",d="Må det heliga ljuset skydda oss på vår expedition till den frusna norden."},
[286264]={h=2761888636,n="Aegwynns silvermynt",d="Jag önskar verkligen att ni magiker kunde få upp huvudet ur era egna ... böcker."},
[286265]={h=1224828329,n="Allerias silvermynt",d="Må mina systrar förverkliga sin fulla potential, så att namnet Windrunner blir känt genom deras gärningar."},
[286266]={h=1874837083,n="Antonidas silvermynt",d="Ge mig styrkan att acceptera det jag inte kan förändra, modet att förändra det jag kan och visheten att skilja det ena från det andra."},
[286267]={h=95009442,n="Arkanist Doans silvermynt",d="Åh, varför lägger du inte märke till mig? Abbendis, jag skulle följa dig vart som helst. Jag önskar att du lade märke till mig ..."},
[286268]={h=4110943334,n="Fandral Staghelms silvermynt",d="Jag ber att jag, när tiden kommer, har styrkan att stå emot krafterna bortom porten."},
[286269]={n="Glödande kristallfragment"},
[286270]={h=4048768831,n="Överuppfinnaren Mekkatorques silvermynt",d="Hur fungerar den här fontänen egentligen? Undrar om jag kunde bygga en själv."},
[286271]={h=1885880434,n="Khadgars silvermynt",d="Turalyon och Alleria, var ni än är, må ni ha det väl."},
[286272]={h=3253176430,n="Kung Terenas Menethils silvermynt",d="Må min son Arthas alltid handla efter sitt folks bästa."},
[286273]={h=3470965334,n="Maiev Shadowsongs silvermynt",d="Var är Illidan?"},
[286274]={h=2374133784,n="Medivhs silvermynt",d="<Du känner hur tre toner ringer i ditt huvud, den tredje knappt hörbar under de andras larm.>"},
[286275]={h=2953825472,n="Prins Magni Bronzebeards silvermynt",d="Jag hoppas att min far och mina bröder överlever mig. Jag blir ingen vidare kung."},
[286279]={h=1344140125,n="Anduin Wrynns guldmynt",d="Jag önskar att jag blev vuxen. Det känns som om jag varit tio år i flera år."},
[286280]={h=240825849,n="Uther Lightbringers guldmynt",d="Unge Arthas måste lära sig tålamod för att tygla sin kraft. Jag ska be att han en dag lär sig leda med omsorg i stället för tvång."},
[286281]={h=2350547459,n="Arthas guldmynt",d="Redan nu har jag ett kungarike i sikte, ett land att härska över. Vad ska jag önska mig? Kanske en fryst scone ..."},
[286283]={h=3681629335,n="Arugals guldmynt",d="Jag önskar att jag en dag får dra mig tillbaka till ett eget prydligt litet gods, med en hel flock sällskapshundar som håller mig sällskap."},
[286284]={h=1503290593,n="Brann Bronzebeards guldmynt",d="Brann Bronzebeard var här."},
[286287]={h=2743799958,n="Kel'Thuzads guldmynt",d="Ibland ... önskar jag att någon kom förbi och gav mig en stor, lång kram."},
[286288]={h=4246230414,n="Lady Jaina Proudmoores guldmynt",d="Arthas, min älskade, kom tillbaka till mig."},
[286290]={h=1731577435,n="Lady Katrana Prestors guldmynt",d="Lyssna, lilla önskefontän. Du ger mig all din kraft om du vet vad som är bäst för dig."},
[286291]={h=1493715504,n="Sylvanas Windrunners guldmynt",d="Jag hoppas att mina systrar och jag får växa upp och gifta oss tillsammans. Det här myntet verkar vara mycket gammalt."},
[286292]={h=2814575776,n="Tirion Fordrings guldmynt",d="Det är min önskan att min käre Taelan blir stark nog att försvara dem han bryr sig om."},
[286293]={h=369649446,n="Archimondes guldmynt",d="Jag vill veta hur du överlevde min vrede, lilla fontän."},
[286294]={h=2398301350,n="Valdrus Blackthornes guldmynt",d="Förklara mina drömmar, lilla fontän. Varför måste jag alltid se på min släkt uppifrån och flytta dem som bönder?"},
[286298]={h=2127852211,n="Umbrinoths guldmynt",d="Det verkar som om mina dagar som extrajobbande brevbärare lider mot sitt slut."},
[286299]={h=2812377165,n="Thralls guldmynt",d="Grom, vila i frid, gamle vän."},
[286300]={h=976835866,n="Sonya Darkhallows guldmynt",d="Det här är meningslöst. Varför lägger jag ett mynt i en fontän?"},
[286302]={h=307914581,n="Zarla Obers guldmynt",d="Så många mynt som glittrar i bassängen. Kanske ingen märker det om jag tar bara ett."},
[286304]={h=474158604,n="En fotsoldats kopparmynt",d="Om jag ändå hade min kusins syssla, att inte göra annat än att släpa runt på ved hur som helst ..."},
[286306]={h=1440210659,n="Vargoths kopparmynt",d="Jag önskar att kapten Sanders skyndade sig med min vinleverans."},
[286307]={h=1973333621,n="Ansirems kopparmynt",d="Jag önskar lycka och acceptans åt min dotter. Hon känner sig så malplacerad här ..."},
[286308]={h=89004977,n="Attumens kopparmynt",d="Kan jag få en bekvämare sadel? Min bakdel värker."},
[286309]={h=644507139,n="Danaths kopparmynt",d="Jag hoppas att ett troll dör, just ... NU."},
[286310]={h=1068737680,n="Elling Trias kopparmynt",d="Det är hårt arbete att vara skurk. En dag hoppas jag få följa mitt livs enda sanna passion ..."},
[286311]={h=1864572137,n="Falstad Wildhammers kopparmynt",d="Jag hoppas att jag så småningom hamnar i ännu en bok."},
